// The Worker entry (wrangler.jsonc "main"): OpenNext's generated worker for every request, plus a `scheduled` handler
// for the Cron Triggers. This is OpenNext's documented "custom worker" set-up: import the generated .open-next/worker.js
// and re-export its fetch next to handlers of our own. Build with `npm run cf:build` first (it writes .open-next/).
// @ts-ignore .open-next/worker.js is generated by `opennextjs-cloudflare build`
import { default as openNext } from "../.open-next/worker.js";
import { runScheduled, type CronEnv } from "../src/lib/cf-scheduled";

type Ctx = { waitUntil(p: Promise<unknown>): void; passThroughOnException(): void };
type Handler = { fetch(req: Request, env: unknown, ctx: Ctx): Promise<Response> };
const app = openNext as Handler;

export default {
  fetch: app.fetch,
  // Runs /api/cron in this same Worker (OpenNext request context, D1/R2 bindings, after() → ctx.waitUntil).
  async scheduled(controller: { cron: string }, env: CronEnv, ctx: Ctx) {
    await runScheduled(controller.cron, env, (req) => app.fetch(req, env, ctx));
  },
};
